mapper.select:
SELECT MAX(t.tran_date)
FROM ACCOUNT_TRANSACTION t
         JOIN ACCOUNT a ON a.account_id = t.account_id
WHERE a.codef_connection_id = #{codefConnectionId}
  AND a.organization_code = #{organizationCode}

mapper.delete:
DELETE FROM ACCOUNT_TRANSACTION
WHERE account_id IN (
    SELECT account_id FROM ACCOUNT
    WHERE user_id = #{userId}
      AND codef_connection_id IN (
          SELECT codef_connection_id FROM CODEF_CONNECTION WHERE provider = #{provider}
      )
)
